def fn(x):
    import string
    # QWERTY order corresponding to a‑z
    qwerty = "qwertyuiopasdfghjklzxcvbnm"
    # create mapping for lowercase letters
    mapping = {a: b for a, b in zip(string.ascii_lowercase, qwerty)}
    result = []
    for ch in x:
        if ch.isalpha():
            low = ch.lower()
            trans = mapping.get(low, low)
            # preserve original case
            result.append(trans.upper() if ch.isupper() else trans)
        else:
            result.append(ch)
    return "".join(result)

